import {
  Timeline,
  TimelineContent,
  TimelineDate,
  TimelineHeader,
  TimelineIndicator,
  TimelineItem,
  TimelineSeparator,
  TimelineTitle,
} from '@/registry/ndeko/ui/timeline';

import { ByWidth } from './_parts/by-width';
import { dayLabelOf } from './_parts/dates';
import { currentStepOf, stepStateOf, StepStateNote } from './_parts/step-state';

type Stage = {
  day: string;
  title: string;
  note: string;
};

type OpeningPlanProps = {
  orientation: 'horizontal' | 'vertical';
};

const CLINIC_OPENING: Stage[] = [
  {
    day: '2026-08-31',
    title: 'Lease signed',
    note: 'Ground floor, Mill Street',
  },
  { day: '2026-09-28', title: 'Fit-out', note: 'Six rooms and a small lab' },
  { day: '2026-10-26', title: 'Team trained', note: 'Front desk and nurses' },
  { day: '2026-11-23', title: 'First patients', note: 'Booking opens online' },
];

const DONE_COUNT = 3;

/* Along the line the date takes the first row: the rail and its dots run under it, and the title starts under the rail. */
const ROW = [
  'group-data-[orientation=horizontal]/timeline:mt-0',
  'group-data-[orientation=vertical]/timeline:not-last:pb-6',
].join(' ');

const UNDER_THE_DATE = 'group-data-[orientation=horizontal]/timeline:top-8';

const DATE_ABOVE_THE_RAIL =
  'group-data-[orientation=horizontal]/timeline:mb-10';

function OpeningPlan({ orientation }: OpeningPlanProps) {
  return (
    <Timeline
      defaultValue={DONE_COUNT}
      orientation={orientation}
      role='list'
      aria-label='Juniper Health clinic opening'
    >
      {CLINIC_OPENING.map((stage, index) => {
        const step = index + 1;
        const state = stepStateOf(step, DONE_COUNT);

        return (
          <TimelineItem
            key={stage.day}
            step={step}
            role='listitem'
            aria-current={currentStepOf(state)}
            className={ROW}
          >
            <TimelineHeader>
              <TimelineIndicator className={UNDER_THE_DATE} />
              <TimelineSeparator className={UNDER_THE_DATE} />
              <TimelineDate
                dateTime={stage.day}
                className={DATE_ABOVE_THE_RAIL}
              >
                {dayLabelOf(stage.day)}
              </TimelineDate>
              <TimelineTitle>
                {stage.title}
                <StepStateNote state={state} />
              </TimelineTitle>
            </TimelineHeader>
            <TimelineContent>{stage.note}</TimelineContent>
          </TimelineItem>
        );
      })}
    </Timeline>
  );
}

export default function Timeline12() {
  return (
    <ByWidth
      narrow={<OpeningPlan orientation='vertical' />}
      wide={<OpeningPlan orientation='horizontal' />}
    />
  );
}

type ByWidthProps = {
  narrow: React.ReactNode;
  wide: React.ReactNode;
};

/*
 * A timeline takes its orientation as a prop, so a piece that lies along a line draws both and its
 * own width decides which one shows: under 576px four columns do not fit, and the list stacks.
 */
export function ByWidth({ narrow, wide }: ByWidthProps) {
  return (
    <div className='@container w-full'>
      <div className='@xl:hidden'>{narrow}</div>
      <div className='@max-xl:hidden'>{wide}</div>
    </div>
  );
}

import { differenceInMinutes, format, parseISO } from 'date-fns';

/* Every time is read against one fixed moment and written without a time zone, so the server and the browser print the same labels. */
const NOW = '2026-11-12T15:00:00';

const MINUTES_PER_HOUR = 60;

const MINUTES_PER_DAY = 1440;

export function dayLabelOf(isoDay: string) {
  const day = parseISO(isoDay);
  return format(day, 'MMM d, yyyy');
}

export function stampLabelOf(isoTime: string) {
  const time = parseISO(isoTime);
  return format(time, "MMMM d, yyyy 'at' HH:mm");
}

function agoOf(count: number, unit: string) {
  if (count === 1) {
    return `1 ${unit} ago`;
  }
  return `${count} ${unit}s ago`;
}

export function agoLabelOf(isoTime: string) {
  const now = parseISO(NOW);
  const time = parseISO(isoTime);
  const minutes = differenceInMinutes(now, time);
  if (minutes < 1) {
    return 'Just now';
  }
  if (minutes < MINUTES_PER_HOUR) {
    return agoOf(minutes, 'minute');
  }
  if (minutes < MINUTES_PER_DAY) {
    const hours = Math.floor(minutes / MINUTES_PER_HOUR);
    return agoOf(hours, 'hour');
  }
  const days = Math.floor(minutes / MINUTES_PER_DAY);
  return agoOf(days, 'day');
}

type StepState = 'done' | 'current' | 'ahead';

const STATE_WORD: Record<StepState, string> = {
  done: 'done',
  current: 'in progress',
  ahead: 'to come',
};

export function stepStateOf(step: number, doneCount: number): StepState {
  if (step <= doneCount) {
    return 'done';
  }
  if (step === doneCount + 1) {
    return 'current';
  }
  return 'ahead';
}

export function currentStepOf(state: StepState) {
  if (state === 'current') {
    return 'step' as const;
  }
  return undefined;
}

type StepStateNoteProps = {
  state: StepState;
};

/* The colour of the marker says where a step stands: this says it in words for a screen reader. */
export function StepStateNote({ state }: StepStateNoteProps) {
  return <span className='sr-only'>, {STATE_WORD[state]}</span>;
}
